"""Guardian-owned reusable SVG history chart with timeline event overlays."""

from __future__ import annotations

from html import escape


def render_history_html(*, configuration_path: str, maintenance_path: str,
                        timeline_path: str) -> str:
    config, maintenance, timeline = [escape(value, quote=True) for value in
                                     (configuration_path, maintenance_path, timeline_path)]
    html = r'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Guardian Zeitverläufe</title>
<style>
:root{color-scheme:light dark;--blue:#0d47a1;--card:var(--card-background-color,#fff);--grid:#78909c38;--axis:#607d8b;--series:#1976d2;--marker:#ef6c00}*{box-sizing:border-box}body{margin:0;font:14px system-ui;background:var(--primary-background-color,#f5f6f8);color:var(--primary-text-color,#222)}header{padding:18px 22px;background:var(--blue);color:#fff}nav{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}nav a{color:#fff;text-decoration:none;padding:8px 12px;border:1px solid #ffffff66;border-radius:8px}nav a.active{background:#fff;color:var(--blue)}main{max-width:1280px;margin:auto;padding:16px}.panel,.chart-card{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 1px 5px #0002;margin-bottom:14px}.controls{display:grid;grid-template-columns:minmax(145px,1.3fr) 72px 100px minmax(175px,1.35fr) minmax(175px,1.35fr) minmax(145px,1.1fr) max-content;gap:8px;align-items:end}.controls label{display:grid;gap:4px;min-width:0}input,select,button{font:inherit;padding:9px;border:1px solid #8888;border-radius:8px;background:transparent;color:inherit;min-width:0}button{cursor:pointer}.primary{background:#1976d2;color:#fff;border:0;white-space:nowrap}.chart-wrap{position:relative;width:100%;height:380px;min-width:0;overflow:hidden}svg{width:100%;height:100%;display:block}.grid{stroke:var(--grid);stroke-width:1;vector-effect:non-scaling-stroke}.axis{stroke:var(--axis);stroke-width:1;vector-effect:non-scaling-stroke}.tick{fill:currentColor;font-size:12px}.series{fill:none;stroke:var(--series);stroke-width:2;vector-effect:non-scaling-stroke}.series.multi{stroke-width:1.3;opacity:.72}.marker{stroke:var(--marker);stroke-width:2;vector-effect:non-scaling-stroke}.marker-hit{stroke:transparent;stroke-width:18;cursor:pointer}.tooltip{position:absolute;pointer-events:none;padding:7px 9px;border-radius:7px;background:#111e;color:#fff;box-shadow:0 2px 8px #0005;white-space:nowrap;z-index:4}.detail{margin-top:10px;padding:10px;border-left:4px solid var(--marker);background:#ef6c0014}.detail a{display:inline-block;margin-top:6px}.muted{opacity:.72}.error{padding:10px;border-left:4px solid #d32f2f;background:#d32f2f18}[hidden]{display:none!important}
@media(max-width:980px){.controls{grid-template-columns:repeat(4,minmax(0,1fr))}.controls button{width:100%}}
@media(max-width:620px){main{padding:10px}.controls{grid-template-columns:repeat(2,minmax(0,1fr))}.controls label:nth-of-type(4),.controls label:nth-of-type(5),.controls button{grid-column:span 2}.chart-wrap{height:310px}.tick{font-size:11px}}
@media(max-width:390px){.panel,.chart-card{padding:10px}.controls{grid-template-columns:1fr}.controls label:nth-of-type(4),.controls label:nth-of-type(5),.controls button{grid-column:1}.chart-wrap{height:285px}}
</style></head><body><header><h1>Guardian Battery</h1><div>Messverläufe mit zeitlichem Maintenance-Kontext</div><nav><a href="__CONFIG__">Konfiguration</a><a href="__MAINTENANCE__">Maintenance-Logbuch</a><a href="__TIMELINE__">Verlauf</a><a class="active" href="history">Zeitverläufe</a></nav></header>
<main><section class="panel"><h2>Guardian-Zeitverlauf</h2><p>Messwerte und Marker bleiben getrennte Quellen. Die Ansicht zeigt zeitliche Korrelation, keine Kausalität.</p><form id="controls" class="controls"><label>Messgröße<select id="metric"><option value="soc">SOC [%]</option><option value="current">Strom [A]</option><option value="cell_voltage">Zellspannung [V]</option><option value="cell_temperature">Zelltemperatur [°C]</option></select></label><label>Modul<select id="module"></select></label><label id="cell-label">Zelle<select id="cell"><option value="">Alle Zellen / Modulebene</option></select></label><label>Von<input id="from" type="datetime-local" required></label><label>Bis<input id="to" type="datetime-local" required></label><label>Aktivitätsfilter<select id="active"><option value="true">Nur aktive</option><option value="all">Alle</option><option value="false">Nur nicht aktive</option></select></label><button class="primary" type="submit">Zeitfenster laden</button></form></section>
<section class="chart-card"><h2 id="chart-title">Zeitverlauf</h2><div id="message"></div><div id="chart" class="chart-wrap" role="img" aria-label="Guardian Messverlauf"><svg id="plot"><g id="phase-layer"></g><g id="grid-layer"></g><g id="series-layer"></g><g id="marker-layer"></g><g id="axis-layer"></g><g id="interaction-layer"></g></svg><div id="tooltip" class="tooltip" hidden></div></div><section id="marker-detail" class="detail" hidden><strong id="marker-title"></strong><div id="marker-meta" class="muted"></div><p id="marker-summary"></p><a id="marker-link">Maintenance-Eintrag öffnen</a></section></section></main>
<script>
const byId=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg';let currentData=null;
const UNITS={soc:'%',current:'A',cell_voltage:'V',cell_temperature:'°C'};
function svg(tag,attrs={}){const node=document.createElementNS(NS,tag);for(const [key,value] of Object.entries(attrs))node.setAttribute(key,String(value));return node}
function localInput(date){const p=n=>String(n).padStart(2,'0');return `${date.getFullYear()}-${p(date.getMonth()+1)}-${p(date.getDate())}T${p(date.getHours())}:${p(date.getMinutes())}`}
function localUtc(value){const date=new Date(value);if(Number.isNaN(date.getTime()))throw Error('Ungültiger lokaler Zeitpunkt.');return date.toISOString()}
function options(id,max){for(let n=1;n<=max;n++){const option=document.createElement('option');option.value=String(n);option.textContent=String(n);byId(id).append(option)}}
function query(){const q=new URLSearchParams({metric:byId('metric').value,module_number:byId('module').value,from:localUtc(byId('from').value),to:localUtc(byId('to').value),active:byId('active').value});if(!byId('cell').disabled&&byId('cell').value)q.set('cell_number',byId('cell').value);return q}
function clear(id){byId(id).replaceChildren()}
function textNode(x,y,value,anchor='middle'){const node=svg('text',{x,y,class:'tick','text-anchor':anchor});node.textContent=value;return node}
function niceStep(range,count){const raw=range/Math.max(1,count),power=10**Math.floor(Math.log10(raw||1)),fraction=raw/power;return (fraction<=1?1:fraction<=2?2:fraction<=5?5:10)*power}
function valueFor(metric,raw){return metric==='cell_voltage'?raw/1000:raw}
function decimals(metric,step){if(metric==='soc')return 0;if(metric==='cell_voltage')return Math.max(2,Math.min(3,Math.ceil(-Math.log10(step||.01))));return step<1?1:0}
function timeLabel(ms,span){const options=span>172800000?{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}:{hour:'2-digit',minute:'2-digit'};return new Intl.DateTimeFormat('de-DE',options).format(new Date(ms))}
function exactTime(ms){return new Intl.DateTimeFormat('de-DE',{dateStyle:'medium',timeStyle:'medium'}).format(new Date(ms))}
function showMarker(marker){byId('marker-detail').hidden=false;byId('marker-title').textContent=marker.title;const parts=[exactTime(Date.parse(marker.timestamp)),marker.module_number?'Position '+marker.module_number:null,marker.module_serial?'Seriennummer '+marker.module_serial:null,marker.cell_number?'Zelle '+marker.cell_number:null].filter(Boolean);byId('marker-meta').textContent=parts.join(' · ');byId('marker-summary').textContent=marker.summary||'';const link=byId('marker-link');link.hidden=!marker.deep_link;if(marker.deep_link)link.href=marker.deep_link}
function render(data){currentData=data;const wrap=byId('chart'),width=Math.max(320,Math.round(wrap.clientWidth)),height=Math.max(250,Math.round(wrap.clientHeight)),margin={left:58,right:18,top:18,bottom:48},plotW=width-margin.left-margin.right,plotH=height-margin.top-margin.bottom,metric=data.series.metric,unit=UNITS[metric];byId('plot').setAttribute('viewBox',`0 0 ${width} ${height}`);for(const id of ['phase-layer','grid-layer','series-layer','marker-layer','axis-layer','interaction-layer'])clear(id);const points=data.series.points.map(point=>({...point,time:Date.parse(point.timestamp),display:valueFor(metric,point.value)})),start=Date.parse(data.window.from),end=Date.parse(data.window.to),span=Math.max(1,end-start),values=points.map(point=>point.display);let min=values.length?Math.min(...values):0,max=values.length?Math.max(...values):1;if(min===max){const pad=Math.abs(min)*.05||1;min-=pad;max+=pad}const yStep=niceStep(max-min,5),yMin=Math.floor(min/yStep)*yStep,yMax=Math.ceil(max/yStep)*yStep||yStep,x=time=>margin.left+(time-start)/span*plotW,y=value=>margin.top+(yMax-value)/(yMax-yMin)*plotH;const grid=byId('grid-layer'),axes=byId('axis-layer');for(let value=yMin,index=0;value<=yMax+yStep/2;value+=yStep,index++){const py=y(value);grid.append(svg('line',{x1:margin.left,y1:py,x2:width-margin.right,y2:py,class:'grid'}));axes.append(textNode(margin.left-8,py+4,`${value.toFixed(decimals(metric,yStep))} ${unit}`,'end'))}const tickCount=Math.max(2,Math.min(8,Math.floor(plotW/110)));for(let index=0;index<=tickCount;index++){const time=start+span*index/tickCount,px=x(time);grid.append(svg('line',{x1:px,y1:margin.top,x2:px,y2:height-margin.bottom,class:'grid'}));axes.append(textNode(px,height-margin.bottom+23,timeLabel(time,span)))}axes.append(svg('line',{x1:margin.left,y1:margin.top,x2:margin.left,y2:height-margin.bottom,class:'axis'}),svg('line',{x1:margin.left,y1:height-margin.bottom,x2:width-margin.right,y2:height-margin.bottom,class:'axis'}));const groups=new Map();for(const point of points){const key=point.cell_number||0;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(point)}for(const [key,group] of groups){const path=group.map((point,index)=>`${index?'L':'M'}${x(point.time).toFixed(2)},${y(point.display).toFixed(2)}`).join(' ');if(path)byId('series-layer').append(svg('path',{d:path,class:'series'+(groups.size>1?' multi':''),'data-cell':key||''}))}for(const marker of data.overlays){const px=x(Date.parse(marker.timestamp));byId('marker-layer').append(svg('line',{x1:px,y1:margin.top,x2:px,y2:height-margin.bottom,class:'marker'}));const hit=svg('line',{x1:px,y1:margin.top,x2:px,y2:height-margin.bottom,class:'marker-hit',tabindex:0,'aria-label':'Maintenance: '+marker.title});hit.addEventListener('click',()=>showMarker(marker));hit.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();showMarker(marker)}});byId('interaction-layer').append(hit)}const tooltip=byId('tooltip');function nearest(event){if(!points.length)return;const rect=wrap.getBoundingClientRect(),mouseX=(event.clientX-rect.left)/rect.width*width,time=start+(mouseX-margin.left)/plotW*span,point=points.reduce((best,item)=>Math.abs(item.time-time)<Math.abs(best.time-time)?item:best);tooltip.textContent=`${exactTime(point.time)} · ${point.display.toFixed(decimals(metric,yStep))} ${unit}${point.cell_number?' · Zelle '+point.cell_number:''}`;tooltip.hidden=false;tooltip.style.left=Math.min(rect.width-210,Math.max(4,event.clientX-rect.left+10))+'px';tooltip.style.top='8px'}wrap.onpointermove=nearest;wrap.onpointerleave=()=>tooltip.hidden=true}
async function load(event){event?.preventDefault();clear('message');byId('marker-detail').hidden=true;try{const response=await fetch('api/history/series?'+query()),data=await response.json();if(!response.ok)throw Error(data.error?.message||'Zeitverlauf nicht verfügbar');byId('chart-title').textContent=byId('metric').selectedOptions[0].textContent;render(data)}catch(error){const box=document.createElement('div');box.className='error';box.textContent=error.message;byId('message').append(box);currentData=null}}
function metricChanged(){const cell=byId('metric').value.startsWith('cell_');byId('cell').disabled=!cell;if(!cell)byId('cell').value=''}
options('module',6);options('cell',15);const end=new Date(),start=new Date(end.getTime()-86400000);byId('from').value=localInput(start);byId('to').value=localInput(end);byId('metric').onchange=metricChanged;metricChanged();byId('controls').onsubmit=load;new ResizeObserver(()=>{if(currentData)render(currentData)}).observe(byId('chart'));load();
</script></body></html>'''
    return (html.replace("__CONFIG__", config)
                .replace("__MAINTENANCE__", maintenance)
                .replace("__TIMELINE__", timeline))
